#!/bin/bash
set -eo pipefail
ROOT='/data1/home/sunyiq/china_radiation_16_hpc_20261012_001/execution_v1/raw_recovery_attempt1'
test -d "$ROOT"
test ! -L "$ROOT"
/data1/home/sunyiq/miniconda3/envs/nh_final/bin/python -B - 'raw_response_part1' 'raw_responses_v1' <<'PY'
import base64,hashlib,json,sys
from pathlib import Path
root=Path('/data1/home/sunyiq/china_radiation_16_hpc_20261012_001/execution_v1/raw_recovery_attempt1')
assert root.is_dir() and not root.is_symlink()
parent=root/'byte_transfers_v1'
assert not parent.is_symlink()
parent.mkdir(exist_ok=True)
folder=parent/sys.argv[1]
folder.mkdir(exist_ok=False)
packet=base64.b64decode('',validate=True)
manifest=base64.b64decode('',validate=True)
assert len(packet)==3929051 and hashlib.sha256(packet).hexdigest()=='c3fff2a8a6433b52cffcbce77a2d35c55030f4b056e0681bb1b7e4c5e1eb1618'
for name,body in [('PAYLOAD.tar.gz',packet),('PACKET_MANIFEST.json',manifest)]:
    with (folder/name).open('xb') as stream:stream.write(body)
source=base64.b64decode('',validate=True)
assert hashlib.sha256(source).hexdigest()=='aa58fb19ba0229a213cdc319bc204ccd393389c366c2818f388f1d00b06a89df'
exec(compile(source,'hpc_ingest_response_bytes.py','exec'),{'__name__':'__main__'})
PY
